1	const MODEL={"type":"gantt","unit":"day","origin":"2026-11-02","span":49.0,"sections":[{"label":"Design","tasks":[{"id":"design","name":"Conflict screen design","tags":[],"start":0.0,"end":14.0}]},{"label":"Build","tasks":[{"id":"engine","name":"Sync engine","tags":[],"start":0.0,"end":21.0},{"id":"screen","name":"Conflict screen build","tags":[],"start":14.0,"end":28.0,"after":["design"]},{"id":"integrate","name":"Desktop and iOS integration","tags":["crit"],"start":28.0,"end":35.0,"after":["engine","screen"],"accent":true}]},{"label":"Launch","tasks":[{"id":"beta","name":"Beta for 5 percent of workspaces","tags":[],"start":35.0,"end":49.0,"after":["integrate"]},{"name":"Release","tags":["milestone"],"start":49.0,"end":49.0,"after":["beta"]}]}],"expect":{"nodes":6,"connectors":5},"title":"Offline mode launch","subtitle":"Which work runs when before the offline mode release, and what holds it","source":"Source: the Loomlist offline mode launch plan. Left out: Android in the next quarter, not yet approved."};
2	const THEME={};
3	const SWATCH={
4	white:['#FFFFFF','#B3B3B3','#1E1E1E'],black:['#1E1E1E','#B3B3B3','#FFFFFF'],
5	darkGray:['#757575','#5E5E5E','#FFFFFF'],violet:['#874FFF','#5427B4','#FFFFFF'],
6	lightBlue:['#C2E5FF','#3DADFF','#1E1E1E'],lightGreen:['#CDF4D3','#66D575','#1E1E1E'],
7	lightYellow:['#FFECBD','#FFC943','#1E1E1E'],lightOrange:['#FFE0C2','#FF9E42','#1E1E1E'],
8	lightRed:['#FFCDC2','#FF7556','#1E1E1E'],lightViolet:['#DCCCFF','#874FFF','#1E1E1E'],
9	lightPink:['#FFC2EC','#F849C1','#1E1E1E'],lightTeal:['#C6FAF6','#5AD8CC','#1E1E1E'],
10	lightGray:['#D9D9D9','#B3B3B3','#1E1E1E'],
11	};
12	const TINT={
13	gray:'#F9F9F9',green:'#EBFFEE',teal:'#F1FEFD',blue:'#F5FBFF',violet:'#F8F5FF',
14	pink:'#FFF0FA',red:'#FFF5F5',orange:'#FFF7F0',yellow:'#FFFBF0',
15	};
16	const D={
17	role:{
18	entry:'lightBlue',neutral:'white',goal:'lightGreen',exit:'lightOrange',error:'lightRed',
19	decision:'lightYellow',store:'lightViolet',io:'lightTeal',client:'lightTeal',gateway:'lightBlue',
20	queue:'lightOrange',external:'lightGray',inProgress:'lightBlue',done:'lightGray',pseudo:'black',
21	junction:'darkGray',marker:'violet',
22	},
23	accent:{pair:'lightPink',node:8,message:4},
24	kind:{
25	initial:{role:'pseudo',key:'Start'},
26	start:{role:'entry',key:'Where it starts'},
27	firstState:{role:'entry',key:'First state'},
28	client:{role:'client',key:'App or client'},
29	gateway:{role:'gateway',key:'Edge or gateway'},
30	participant:{role:'neutral',key:'Participant'},
31	screen:{role:'neutral',key:'Screen or step'},
32	step:{role:'neutral',key:'Step'},
33	state:{role:'neutral',key:'State'},
34	service:{role:'neutral',key:'Service'},
35	subprocess:{role:'neutral',key:'Sub-process'},
36	io:{role:'io',key:'Input or output'},
37	entity:{role:'neutral',key:'Entity'},
38	queue:{role:'queue',key:'Queue or stream'},
39	decision:{role:'decision',key:'Decision'},
40	choice:{role:'decision',key:'Choice'},
41	fork:{role:'pseudo',key:'Fork or join'},
42	merge:{role:'junction',key:'Paths join'},
43	success:{role:'goal',key:'Goal reached'},
44	exit:{role:'exit',key:'Leaves the flow'},
45	error:{role:'error',key:'Error or blocked'},
46	finalState:{role:'done',key:'Final state'},
47	final:{role:'pseudo',key:'End'},
48	datastore:{role:'store',key:'Data store'},
49	external:{role:'external',key:'Outside system'},
50	done:{role:'done',key:'Done'},
51	active:{role:'inProgress',key:'In progress'},
52	planned:{role:'neutral',key:'Planned'},
53	crit:{role:'error',key:'Critical, heavy outline'},
54	milestone:{role:'decision',key:'Milestone'},
55	focus:{key:'In focus'},
56	},
57	type:{family:'Inter',title:64,subtitle:28,zone:24,node:20,label:18,field:16,small:14},
58	line:{color:'#757575',async:'#3DADFF',lifeline:'#B3B3B3',weight:2},
59	zone:{cycle:['blue','orange','teal','yellow','violet']},
60	key:{
61	title:'Key',tint:'gray',pin:'Step number',dashedOptional:'Optional or proposed',
62	dashedAsync:'Async or outside call',identifying:'Identifying',nonIdentifying:'Non-identifying',
63	twoWay:'Both ways',request:'Request',reply:'Reply',async:'Async message',asyncReply:'Async reply',
64	},
65	};
66	const T=(function merge(a,b){
67	for(const k in b)a[k]=b[k]&&typeof b[k]==='object'&&!Array.isArray(b[k])&&a[k]?merge(a[k],b[k]):b[k];
68	return a;
69	})(D,THEME);
70	const SHAPES={
71	decision:'DIAMOND',choice:'DIAMOND',milestone:'DIAMOND',merge:'ELLIPSE',initial:'ELLIPSE',
72	final:'ELLIPSE',datastore:'ENG_DATABASE',queue:'ENG_QUEUE',subprocess:'PREDEFINED_PROCESS',
73	io:'PARALLELOGRAM_RIGHT',fork:'SQUARE',entity:'SQUARE',
74	};
75	const FIXED={merge:[24,24],initial:[32,32],final:[32,32],choice:[56,56],fork:[16,96],milestone:[32,32]};
76	const OUTLINE={final:'ring',crit:'heavy',planned:'line'};
77	const shapeOf=(kind)=>SHAPES[kind]||'ROUNDED_RECTANGLE';
78	const pairOf=(kind)=>SWATCH[kind==='focus'?T.accent.pair:T.role[T.kind[kind].role]]||SWATCH.white;
79	const ACCENT=SWATCH[T.accent.pair][1];
80	const INK='#1E1E1E';
81	const OFF_PATH=new Set(['exit','error']);
82	const ERD={1:'ERD_EXACTLY_ONE','?':'ERD_ZERO_OR_ONE','*':'ERD_ZERO_OR_MORE','+':'ERD_ONE_OR_MORE'};
83	const ROUND=new Set(['DIAMOND','ELLIPSE','HEXAGON','OCTAGON']);
84	const GRID=8;
85	const snap=(v)=>Math.round(v/GRID)*GRID;
86	const up8=(v)=>Math.ceil(v/GRID)*GRID;
87	const TYPE=T.type;
88	const PARA=4;
89	const RANK_GAP=136;
90	const CROSS_GAP=80;
91	const ZONE_GAP=48;
92	const ZONE_HEAD=96;
93	const ZONE_PAD=48;
94	const BOARD_PAD=80;
95	const solid=(x)=>[{type:'SOLID',color:{r:parseInt(x.slice(1,3),16)/255,g:parseInt(x.slice(3,5),16)/255,b:parseInt(x.slice(5,7),16)/255}}];
96	const warnings=[];
97	const created=[];
98	const elements=[];
99	const links=[];
100	const STYLES=['Medium','Regular','Semi Bold','Bold'];
101	const load=(family)=>Promise.all(STYLES.map((style)=>figma.loadFontAsync({family,style}).then(()=>style,(err)=>{
102	if(style!=='Semi Bold')throw err;
103	return figma.loadFontAsync({family,style:'SemiBold'}).then(()=>'SemiBold');
104	})));
105	let FAMILY=TYPE.family,NAMES;
106	try{NAMES=await load(FAMILY);}catch(err){warnings.push(`the font ${FAMILY} did not load, so the board is set in Inter`);FAMILY='Inter';NAMES=await load(FAMILY);}
107	const[MEDIUM,REGULAR,SEMI,BOLD]=NAMES.map((style)=>({family:FAMILY,style}));
108	const measurer=figma.createText();
109	measurer.fontName=MEDIUM;
110	function natural(chars,font,size){
111	measurer.fontName=font;
112	measurer.fontSize=size;
113	measurer.textAutoResize='WIDTH_AND_HEIGHT';
114	measurer.characters=chars||' ';
115	return{w:measurer.width,h:measurer.height};
116	}
117	function fit(label,type){
118	const round=ROUND.has(type);
119	const tall=type==='ENG_DATABASE'||type==='ENG_QUEUE';
120	const w0=round?256:224;
121	const h0=round?160:(tall?128:96);
122	measurer.fontName=MEDIUM;
123	measurer.fontSize=TYPE.node;
124	measurer.textAutoResize='HEIGHT';
125	let w=w0,hh=h0;
126	for(let s=1;s<3;s+=0.1){
127	w=w0*s;hh=h0*s;
128	const aw=round?w/2-32:w-(type==='PARALLELOGRAM_RIGHT'?96:48);
129	const ah=round?hh/2-32:hh-(tall?64:40);
130	measurer.resize(Math.max(aw,1),measurer.height);
131	measurer.characters=label||' ';
132	if(measurer.height<=ah)break;
133	}
134	return{w:up8(w),h:up8(hh)};
135	}
136	function text(parent,chars,font,size,x,y,width){
137	const t=figma.createText();
138	t.fontName=font;
139	t.fontSize=size;
140	t.characters=chars;
141	t.fills=solid(INK);
142	parent.appendChild(t);
143	if(width){t.textAutoResize='HEIGHT';t.resize(width,t.height);}
144	t.x=x;
145	t.y=y;
146	created.push(t.id);
147	return t;
148	}
149	function paint(s,kind,accent){
150	const pair=pairOf(kind),o=OUTLINE[kind];
151	const hot=accent||kind==='focus';
152	s.fills=solid(pair[0]);
153	s.strokes=solid(hot?ACCENT:o==='line'?T.line.color:pair[1]);
154	try{s.strokeWeight=hot?T.accent.node:o==='ring'?6:o==='heavy'?4:2;}catch(err){}
155	return pair;
156	}
157	function shape(parent,kind,label,x,y,w,hh,name,size,accent){
158	const s=figma.createShapeWithText();
159	s.shapeType=shapeOf(kind);
160	s.name=name;
161	const pair=paint(s,kind,accent);
162	if(label){
163	s.text.fontName=MEDIUM;
164	s.text.fontSize=size||TYPE.node;
165	s.text.characters=label;
166	s.text.fills=solid(pair[2]);
167	}
168	s.resize(w,hh);
169	parent.appendChild(s);
170	s.x=x;
171	s.y=y;
172	created.push(s.id);
173	return s;
174	}
175	function marker(parent,digit,x,y,name){
176	const p=shape(parent,'initial',digit,x,y,32,32,name,TYPE.small);
177	const m=SWATCH[T.role.marker];
178	p.fills=solid(m[0]);
179	p.strokes=solid(m[1]);
180	p.text.fills=solid(m[2]);
181	return p;
182	}
183	function anchor(parent,cx,cy,name){
184	const a=figma.createShapeWithText();
185	a.shapeType='ELLIPSE';
186	a.name=name;
187	a.fills=[];
188	a.strokes=[];
189	a.resize(16,16);
190	parent.appendChild(a);
191	a.x=cx-8;
192	a.y=cy-8;
193	created.push(a.id);
194	return a;
195	}
196	function end(node,magnet){
197	if(magnet==='POINT')return{endpointNodeId:node.id,position:{x:node.width/2,y:node.height/2}};
198	return{endpointNodeId:node.id,magnet:magnet||'AUTO'};
199	}
200	function connect(parent,from,to,o){
201	const c=figma.createConnector();
202	parent.appendChild(c);
203	c.name=o.name;
204	c.connectorLineType=o.line||'ELBOWED';
205	c.connectorStart=end(from,o.m0);
206	c.connectorEnd=end(to,o.m1);
207	c.connectorStartStrokeCap=o.startCap||'NONE';
208	c.connectorEndStrokeCap=o.endCap===undefined?'ARROW_LINES':o.endCap;
209	c.strokes=solid(o.color||T.line.color);
210	c.strokeWeight=o.weight||T.line.weight;
211	c.dashPattern=o.dashed?[10,6]:[];
212	if(o.label){
213	c.text.fontName=MEDIUM;
214	c.text.fontSize=TYPE.label;
215	c.text.characters=o.label;
216	}
217	created.push(c.id);
218	return c;
219	}
220	function zoneSection(parent,label,tint,x,y,w,hh){
221	const sec=figma.createSection();
222	parent.appendChild(sec);
223	sec.name=label;
224	sec.x=x;
225	sec.y=y;
226	sec.resize(w,hh);
227	sec.fills=solid(TINT[tint]||TINT.gray);
228	created.push(sec.id);
229	text(sec,label,SEMI,TYPE.zone,32,32);
230	return sec;
231	}
232	const tinted=[];
233	function tintFor(i,kinds,label,x,y,w,h){
234	const c=T.zone.cycle,g=2*ZONE_GAP,order=[...c.slice(i%c.length),...c.slice(0,i%c.length)];
235	const hues=new Set(kinds.map((k)=>(T.role[(T.kind[k]||{}).role]||T.accent.pair).replace('light','').toLowerCase()));
236	const near=tinted.filter((z)=>z.x<x+w+g&&x<z.x+z.w+g&&z.y<y+h+g&&y<z.y+z.h+g).map((z)=>z.t);
237	let t=order.find((t)=>!hues.has(t)&&!near.includes(t));
238	if(!t){
239	t=order.find((t)=>!near.includes(t))||order[0];
240	warnings.push(`zone ${label} repeats the ${t} tint of ${near.includes(t) ? 'a zone beside it' : 'a step inside it'}, because the tint cycle has none left for it`);
241	}
242	tinted.push({x,y,w,h,t});
243	return t;
244	}
245	const ARROWS={
246	request:{cap:'ARROW_EQUILATERAL'},
247	reply:{dashed:true,cap:'ARROW_EQUILATERAL'},
248	async:{cap:'ARROW_LINES',color:T.line.async},
249	asyncReply:{dashed:true,cap:'ARROW_LINES',color:T.line.async},
250	focus:{cap:'ARROW_EQUILATERAL',color:ACCENT,weight:T.accent.message},
251	};
252	const MONTHS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
253	function buildGantt(M){
254	const day=M.unit==='day';
255	const span=Math.max(1,M.span);
256	const scale=day?Math.min(96,Math.max(8,snap(1680/span))):Math.min(8,Math.max(1,1680/span));
257	const tick=day?(span<=14?1:span<=70?7:span<=200?14:28):(span<=180?30:60);
258	const tasks=M.sections.flatMap((s)=>s.tasks);
259	const nameCol=up8(Math.max(240,...tasks.map((t)=>natural(t.name,MEDIUM,TYPE.label).w+48),
260	...M.sections.map((s)=>natural(s.label,SEMI,TYPE.zone).w+64)));
261	const AXIS=56,ROW=56,BAR=32,HEAD=72;
262	const timeW=up8(span*scale);
263	const width=nameCol+timeW+48;
264	let y=AXIS;
265	const bands=M.sections.map((s)=>{
266	const band={y,h:HEAD+s.tasks.length*ROW+16};
267	y+=band.h+16;
268	return band;
269	});
270	const height=y-16;
271	const label=(offset)=>{
272	if(day){
273	const d=new Date(`${M.origin}T00:00:00Z`);
274	d.setUTCDate(d.getUTCDate()+offset);
275	return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]}`;
276	}
277	const[hh,mm]=M.origin.split(':').map(Number);
278	const total=hh*60+mm+offset;
279	return `${String(Math.floor(total / 60) % 24).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
280	};
281	const length=(t)=>{
282	const d=t.end-t.start;
283	if(day)return d%7===0?`${d / 7} week${d === 7 ? '' : 's'}`:`${d} day${d === 1 ? '' : 's'}`;
284	return d>=60&&d%60===0?`${d / 60} h`:`${d} min`;
285	};
286	const statusOf=(t)=>(t.tags.includes('milestone')?'milestone':t.tags.includes('crit')?'crit'
287	:t.tags.includes('active')?'active':t.tags.includes('done')?'done':'planned');
288	const marked=tasks.find((t)=>t.accent);
289	const key=[...new Set(tasks.map(statusOf))].map((kind)=>({kind})).concat(marked?[{kind:'focus',like:statusOf(marked)}]:[]);
290	return{
291	width,height,key,
292	draw(board,ox,oy){
293	const ticks=[],bars=new Map();
294	for(let t=0;t<=span;t+=tick)ticks.push(t);
295	const rule=(parent,x,top,hh,name)=>{
296	const r=figma.createRectangle();
297	parent.appendChild(r);
298	r.name=name;
299	r.fills=solid('#D9D9D9');
300	r.resize(1,Math.max(1,hh));
301	r.x=x;
302	r.y=top;
303	created.push(r.id);
304	};
305	ticks.forEach((t)=>{
306	const x=ox+nameCol+t*scale;
307	const tl=text(board,label(t),REGULAR,TYPE.label,x,oy+8);
308	tl.x=x-tl.width/2;
309	rule(board,x,oy+AXIS-8,height-AXIS+8,`grid:${t}`);
310	});
311	M.sections.forEach((s,i)=>{
312	const band=bands[i];
313	const sec=zoneSection(board,s.label,tintFor(i,s.tasks.map(statusOf),s.label,ox,oy+band.y,width,band.h),ox,oy+band.y,width,band.h);
314	ticks.forEach((t)=>rule(sec,nameCol+t*scale,0,band.h,`grid:${t}`));
315	s.tasks.forEach((t,k)=>{
316	const ry=HEAD+k*ROW;
317	text(sec,t.name,MEDIUM,TYPE.label,32,ry+(ROW-20)/2-4);
318	const status=statusOf(t);
319	const bx=nameCol+t.start*scale;
320	let bar;
321	if(status==='milestone'){
322	bar=shape(sec,'milestone','',bx-16,ry+(ROW-32)/2-4,32,32,`node:${t.id || t.name}`,0,t.accent);
323	}else{
324	const w=Math.max(16,(t.end-t.start)*scale);
325	const words=status==='crit'?`${length(t)}, critical`:length(t);
326	const fits=natural(words,MEDIUM,TYPE.small).w+24<=w;
327	bar=shape(sec,status,fits?words:'',bx,ry+(ROW-BAR)/2-4,w,BAR,`node:${t.id || t.name}`,TYPE.small,t.accent);
328	}
329	elements.push({id:bar.id,model:t.id||t.name,kind:status,text:t.name});
330	bars.set(t.id||t.name,bar);
331	});
332	});
333	tasks.forEach((t)=>(t.after||[]).forEach((id)=>{
334	const me=t.id||t.name,from=bars.get(id),to=bars.get(me);
335	if(!from)return warnings.push(`no task ${id} for ${me} to follow`);
336	const ms=statusOf(t)==='milestone';
337	const c=connect(board,from,to,{name:`edge:${id}->${me}`,m0:ms?'BOTTOM':'RIGHT',m1:ms?'LEFT':'TOP'});
338	links.push({id:c.id,from:from.id,to:to.id,model:`${id}->${me}`,label:''});
339	}));
340	},
341	};
342	}
343	const builders={gantt:buildGantt};
344	let body;
345	try{
346	body=builders[MODEL.type](MODEL);
347	}catch(err){
348	measurer.remove();
349	throw err;
350	}
351	const page=figma.currentPage;
352	const others=page.children.filter((n)=>n.id!==measurer.id);
353	const board=figma.createSection();
354	board.name=MODEL.title;
355	board.fills=solid('#FFFFFF');
356	board.x=others.length?snap(Math.max(...others.map((n)=>n.x+n.width))+400):0;
357	board.y=others.length?snap(Math.min(...others.map((n)=>n.y))):0;
358	created.push(board.id);
359	const wrap=Math.min(Math.max(body.width,960),1440);
360	const title=text(board,MODEL.title,BOLD,TYPE.title,BOARD_PAD,BOARD_PAD);
361	let cursor=title.y+title.height+16;
362	if(MODEL.subtitle){
363	const sub=text(board,MODEL.subtitle,REGULAR,TYPE.subtitle,BOARD_PAD,cursor,wrap);
364	const lines=sub.height;
365	if(lines>TYPE.subtitle*1.6){
366	let lo=wrap/2,hi=wrap;
367	while(hi-lo>8){const w=(lo+hi)/2;sub.resize(w,sub.height);if(sub.height>lines)lo=w;else hi=w;}
368	sub.resize(hi,sub.height);
369	}
370	cursor=sub.y+sub.height;
371	}
372	const ox=BOARD_PAD;
373	const oy=up8(cursor+64);
374	body.draw(board,ox,oy);
375	const key=figma.createSection();
376	board.appendChild(key);
377	key.name='Key';
378	key.fills=solid(TINT[T.key.tint]||TINT.gray);
379	key.x=BOARD_PAD;
380	key.y=oy+body.height+64;
381	created.push(key.id);
382	text(key,T.key.title,SEMI,TYPE.zone,32,32);
383	const LINES={
384	dashedOptional:{dashed:true},dashedAsync:{dashed:true},identifying:{cap:'NONE'},
385	nonIdentifying:{dashed:true,cap:'NONE'},twoWay:{start:'ARROW_LINES'},
386	};
387	const KINDS=Object.keys(T.kind),LINE_ORDER=Object.keys(LINES),ARROW_ORDER=Object.keys(ARROWS);
388	const placeOf=(it)=>(it.kind==='focus'||it.arrow==='focus'?999:it.kind?KINDS.indexOf(it.kind)
389	:it.line?100+LINE_ORDER.indexOf(it.line):it.arrow?200+ARROW_ORDER.indexOf(it.arrow):300);
390	const keyWidth=Math.max(body.width,480);
391	let kx=32,ky=88,kr=0;
392	for(const item of body.key.sort((a,b)=>placeOf(a)-placeOf(b))){
393	const x0=kx,made=[];
394	let label;
395	if(item.kind){
396	const as=item.like||item.kind,f=FIXED[as],sh=shapeOf(as);
397	const tall=sh==='ENG_DATABASE'||sh==='ENG_QUEUE';
398	const sw=f?Math.min(f[0],56):(ROUND.has(sh)?72:(tall?48:88));
399	const sht=f?Math.min(f[1],56):(ROUND.has(sh)||tall?56:48);
400	const sample=shape(key,as,'',kx,ky,sw,sht,`key:${item.kind}`,0,!!item.like);
401	sample.y=ky+(56-sample.height)/2;
402	made.push(sample);
403	kx+=sample.width+16;
404	label=T.kind[item.kind].key;
405	}else if(item.pin){
406	made.push(marker(key,'1',kx,ky+12,'key:pin'));
407	kx+=48;
408	label=T.key.pin;
409	}else{
410	const spec=item.arrow?ARROWS[item.arrow]:LINES[item.line];
411	if(!spec)continue;
412	const name=item.arrow||item.line;
413	const a=anchor(key,kx+8,ky+28,`key:${name}:a`);
414	const b=anchor(key,kx+88,ky+28,`key:${name}:b`);
415	connect(key,a,b,{name:`key:${name}`,line:'STRAIGHT',m0:'POINT',m1:'POINT',
416	dashed:spec.dashed,endCap:spec.cap===undefined?'ARROW_LINES':spec.cap,startCap:spec.start||'NONE',
417	color:spec.color,weight:spec.weight});
418	made.push(a,b);
419	kx+=112;
420	label=name==='focus'?T.kind.focus.key:T.key[name];
421	}
422	const t=text(key,label,REGULAR,TYPE.label,kx,ky+18);
423	made.push(t);
424	if(t.x+t.width>keyWidth-32&&x0>32){
425	made.forEach((n)=>{n.x+=32-x0;n.y+=72;});
426	ky+=72;
427	}
428	kr=Math.max(kr,t.x+t.width);
429	kx=up8(t.x+t.width+48);
430	}
431	key.resize(Math.max(keyWidth,up8(kr+32)),ky+88);
432	let bottom=key.y+key.height;
433	if(MODEL.source){
434	const src=text(board,MODEL.source,REGULAR,TYPE.label,BOARD_PAD,bottom+32,wrap);
435	bottom=src.y+src.height;
436	}
437	measurer.remove();
438	const right=Math.max(...board.children.map((n)=>n.x+n.width));
439	board.resize(up8(right+BOARD_PAD),up8(bottom+BOARD_PAD));
440	const counts={nodes:elements.length,connectors:links.length};
441	const expect=MODEL.expect||{};
442	for(const[k,v]of Object.entries(expect)){
443	if(counts[k]!==undefined&&counts[k]!==v)warnings.push(`${k}: drew ${counts[k]}, the model has ${v}`);
444	}
445	const TAG='productowner';
446	let tagged=true;
447	try{
448	board.setSharedPluginData(TAG,MODEL.title,JSON.stringify({written:new Date().toISOString(),counts,design:THEME.id||'built-in'}));
449	}catch(err){
450	tagged=false;
451	warnings.push(`the board was not tagged: ${err.message}`);
452	}
453	await board.screenshot({scale:Math.min(1,1600/board.width)});
454	return{
455	boardId:board.id,
456	tag:tagged?{namespace:TAG,key:MODEL.title}:null,
457	bounds:{x:board.x,y:board.y,w:board.width,h:board.height},
458	counts,
459	expect,
460	elements,
461	links,
462	warnings,
463	createdCount:created.length,
464	};

